# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAREKÖKLÜ İFADELERDE TOPLAMA VE ÇIKARMA İŞLEMLERİ</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="73" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Kök İçleri Aynı Olan İfadeler</text>\n  <text x="182" y="102" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e3a8a">a·kök(x) + b·kök(x) - c·kök(x) = (a + b - c)·kök(x)</text>\n  <text x="40" y="130" font-size="11.5" fill="#334155">• Kök içindeki sayı aynen kalır, değiştirilmez.</text>\n  <text x="40" y="152" font-size="11.5" fill="#334155">• Yalnızca kök önündeki katsayılar toplanır/çıkarılır.</text>\n  <text x="40" y="178" font-size="11.5" font-weight="bold" fill="#1d4ed8">Örnek: 6·kök(5) + 3·kök(5) - kök(5) = 8·kök(5)</text>\n  <text x="40" y="204" font-size="11.5" font-weight="bold" fill="#b91c1c">Dikkat: kök(a) + kök(b) ≠ kök(a + b)</text>\n  <text x="40" y="224" font-size="10.5" fill="#475569">kök(16) + kök(9) = 4 + 3 = 7 (kök(25) = 5 değildir!)</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="73" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Kök İçleri Farklı Olan İfadeler</text>\n  <text x="375" y="100" font-size="11.5" fill="#334155">• Terimler önce a·kök(b) biçimine getirilir.</text>\n  <text x="375" y="122" font-size="11.5" fill="#334155">• Kök içleri eşitlenen terimler kendi arasında toplanır.</text>\n  <text x="375" y="148" font-size="11.5" font-weight="bold" fill="#14532d">Örnek: kök(75) + kök(48) - kök(12)</text>\n  <text x="385" y="170" font-size="11.5" fill="#334155">= 5·kök(3) + 4·kök(3) - 2·kök(3)</text>\n  <text x="385" y="192" font-size="12" font-weight="bold" fill="#15803d">= (5 + 4 - 2)·kök(3) = 7·kök(3)</text>\n  <text x="375" y="220" font-size="11" fill="#475569">Kök içleri eşitlenemiyorsa işlem aynen bırakılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GEOMETRİK ŞEKİLLERDE ÇEVRE VE UZUNLUK UYGULAMALARI</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Dikdörtgenin Çevre Uzunluğu</text>\n  <rect x="85" y="88" width="195" height="68" rx="4" fill="#fef08a" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="106" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#713f12">Uzun Kenar = kök(50) = 5·kök(2) cm</text>\n  <text x="182" y="142" text-anchor="middle" font-size="11" fill="#854d0e">Kısa Kenar = kök(18) = 3·kök(2) cm</text>\n  <text x="45" y="182" font-size="11.5" fill="#334155">• Çevre = 2 · (Kısa Kenar + Uzun Kenar)</text>\n  <text x="45" y="204" font-size="11.5" font-weight="bold" fill="#854d0e">• Çevre = 2 · (3·kök(2) + 5·kök(2))</text>\n  <text x="45" y="224" font-size="12" font-weight="bold" fill="#15803d">• Çevre = 2 · 8·kök(2) = 16·kök(2) cm</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Alanı Verilen Karesel Bölgeler</text>\n  <text x="375" y="98" font-size="11.5" fill="#334155">• Alanı A olan karenin bir kenarı: <tspan font-weight="bold" fill="#9d174d">a = kök(A)</tspan></text>\n  <text x="375" y="122" font-size="11.5" fill="#334155">• Karenin çevre uzunluğu: <tspan font-weight="bold" fill="#9d174d">Çevre = 4 · a</tspan></text>\n  <text x="375" y="150" font-size="11.5" font-weight="bold" fill="#831843">Örnek: Alanları 27 cm² ve 12 cm² olan</text>\n  <text x="375" y="168" font-size="11.5" font-weight="bold" fill="#831843">iki karenin yan yana taban uzunluğu:</text>\n  <text x="385" y="192" font-size="11.5" fill="#334155">1. Kenar = kök(27) = 3·kök(3) cm</text>\n  <text x="385" y="212" font-size="11.5" fill="#334155">2. Kenar = kök(12) = 2·kök(3) cm</text>\n  <text x="385" y="230" font-size="11.5" font-weight="bold" fill="#be185d">Toplam = 3·kök(3) + 2·kök(3) = 5·kök(3) cm</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAREKÖKLÜ BİR İFADEYİ DOĞAL SAYI YAPAN ÇARPANLAR (M.8.1.3.6)</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="73" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Temel Kural ve Yöntem</text>\n  <text x="40" y="100" font-size="11.5" fill="#334155">1. Kareköklü ifade önce <tspan font-weight="bold">a·kök(b)</tspan> biçimine</text>\n  <text x="52" y="117" font-size="11.5" fill="#334155">getirilir (b içinde tam kare çarpan kalmaz).</text>\n  <text x="40" y="142" font-size="11.5" fill="#334155">2. Kök içindeki b sayısını kökten kurtarmak</text>\n  <text x="52" y="159" font-size="11.5" fill="#334155">için ifade <tspan font-weight="bold" fill="#1d4ed8">kök(b)</tspan> veya katları olan <tspan font-weight="bold" fill="#1d4ed8">k·kök(b)</tspan></text>\n  <text x="52" y="176" font-size="11.5" fill="#334155">ile çarpılmalıdır:</text>\n  <text x="182" y="206" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e3a8a">a·kök(b) · k·kök(b) = a · k · b (Doğal Sayı)</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="73" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Örnek: kök(24) İfadesinin Çarpanları</text>\n  <text x="375" y="100" font-size="12" font-weight="bold" fill="#14532d">• kök(24) = kök(4 · 6) = 2·kök(6)</text>\n  <text x="375" y="126" font-size="11.5" fill="#334155">İçinde <tspan font-weight="bold">kök(6)</tspan> bulunan her çarpan doğal sayı yapar:</text>\n  <text x="385" y="150" font-size="11.5" fill="#334155">✓ 1·kök(6) = <tspan font-weight="bold" fill="#15803d">kök(6)</tspan> → 2·kök(6) · kök(6) = 12</text>\n  <text x="385" y="174" font-size="11.5" fill="#334155">✓ 2·kök(6) = <tspan font-weight="bold" fill="#15803d">kök(24)</tspan> → 2·kök(6) · 2·kök(6) = 24</text>\n  <text x="385" y="198" font-size="11.5" fill="#334155">✓ 3·kök(6) = <tspan font-weight="bold" fill="#15803d">kök(54)</tspan> → 2·kök(6) · 3·kök(6) = 36</text>\n  <text x="385" y="222" font-size="11.5" fill="#334155">✓ 5·kök(6) = <tspan font-weight="bold" fill="#15803d">kök(150)</tspan> → 2·kök(6) · 5·kök(6) = 60</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
